CREATE TABLE IF NOT EXISTS telemetry_normalized.canonical_fact_v1 (fact_id UUID,fact_hash FixedString(64),fact_type LowCardinality(String),fact_version LowCardinality(String),source_system LowCardinality(String),source_product String,source_record_id String,source_record_hash FixedString(64),source_schema_name LowCardinality(String),source_schema_version LowCardinality(String),tenant_id String,project_id String,environment LowCardinality(String),source_instance_urn String,occurred_at DateTime64(3,'UTC'),received_at DateTime64(3,'UTC'),normalized_at DateTime64(3,'UTC'),entity_refs_json String,relations_json String,correlation_json String,payload_json String,normalizer_id LowCardinality(String),normalizer_version UInt32,mapping_version UInt32,policy_version UInt32) ENGINE=ReplacingMergeTree(normalized_at) PARTITION BY toYYYYMM(occurred_at) ORDER BY (tenant_id,project_id,fact_type,occurred_at,fact_id);
CREATE TABLE IF NOT EXISTS telemetry_normalized.canonical_entity_ref_v1 (fact_id UUID,tenant_id String,project_id String,entity_type LowCardinality(String),entity_urn String,local_id String,created_at DateTime64(3,'UTC')) ENGINE=ReplacingMergeTree(created_at) ORDER BY (tenant_id,project_id,entity_urn,fact_id);
CREATE TABLE IF NOT EXISTS telemetry_normalized.canonical_relation_candidate_v1 (candidate_id UUID,fact_id UUID,tenant_id String,project_id String,relation_type LowCardinality(String),source_entity_urn String,target_entity_urn String,evidence_class LowCardinality(String),candidate_json String,created_at DateTime64(3,'UTC')) ENGINE=ReplacingMergeTree(created_at) ORDER BY (tenant_id,project_id,candidate_id);
CREATE TABLE IF NOT EXISTS telemetry_normalized.normalization_dead_letter_v1 (dlq_id UUID,source_system LowCardinality(String),source_record_id String,normalizer_id String,error_code String,error_summary String,created_at DateTime64(3,'UTC'),resolved_at Nullable(DateTime64(3,'UTC'))) ENGINE=MergeTree PARTITION BY toYYYYMM(created_at) ORDER BY (source_system,created_at,dlq_id);
